import { getMetaContent } from "helpers/meta_helpers"

const MS_PER_DAY = 1000 * 60 * 60 * 24

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MS_PER_DAY)
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInTimezone(date)
  return new Date(Date.UTC(year, month - 1, day))
}

export function isSameYear(date, otherDate) {
  return datePartsInTimezone(date).year === datePartsInTimezone(otherDate).year
}

// Format in the same timezone as the day boundaries above, and in the page's language so that
// dates read naturally within the surrounding copy.
export function formatDate(date, options) {
  return withPlainSpaces(dateFormatter(pageLanguage(), options).format(date))
}

export function formatRelativeToParts(value, unit) {
  return relativeFormatter(pageLanguage()).formatToParts(value, unit).map(part => ({ ...part, value: withPlainSpaces(part.value) }))
}

// Snap a timestamp to midnight using the timezone the server rendered with (the
// `timezone` meta tag), so client day boundaries match the server's instead of
// following the browser's resolved timezone, which can differ in a PWA.
function datePartsInTimezone(date) {
  return dateFormatter("en-US", { year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(date).reduce((parts, { type, value }) => {
    if (type !== "literal") parts[type] = parseInt(value, 10)
    return parts
  }, {})
}

function pageLanguage() {
  return document.documentElement.lang || "en"
}

// Newer versions of ICU put a narrow no-break space before AM/PM ("1:42 PM")
function withPlainSpaces(string) {
  return string.replaceAll("\u202f", " ")
}

const dateFormatters = new Map()
const relativeFormatters = new Map()

function dateFormatter(locale, options) {
  const timezone = getMetaContent("timezone")
  const key = JSON.stringify([ locale, timezone, options ])

  if (!dateFormatters.has(key)) {
    dateFormatters.set(key, buildDateFormatter(locale, timezone, options))
  }

  return dateFormatters.get(key)
}

function buildDateFormatter(locale, timezone, options) {
  try {
    return new Intl.DateTimeFormat(locale, { ...options, timeZone: timezone })
  } catch {
    return new Intl.DateTimeFormat(locale, options)
  }
}

function relativeFormatter(locale) {
  if (!relativeFormatters.has(locale)) {
    relativeFormatters.set(locale, new Intl.RelativeTimeFormat(locale, { numeric: "auto" }))
  }

  return relativeFormatters.get(locale)
}
EOF

