export function beginningOfDay(date) {
  const { year, month, day } = datePartsInTimezone(date)
  return new Date(Date.UTC(year, month - 1, day))
}

export function isSameYear(date, otherDate) {
  return datePartsInTimezone(date).year === datePartsInTimezone(otherDate).year
}

// Format in the same timezone as the day boundaries above, and in the page's language so that
// dates read naturally within the surrounding copy.
export function formatDate(date, options) {
  return withPlainSpaces(dateFormatter(pageLanguage(), options).format(date))
}

export function formatRelativeToParts(value, unit) {
